(function() {
    'use strict';

    class GovernanceAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Board Effectiveness: Corporate Governance';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    titleKey: 'round1_title',
                    briefingKey: 'round1_briefing',
                    decALabelKey: 'r1_decA_label',
                    decBLabelKey: 'r1_decB_label',
                    decAOptions: [
                        { value: 'exceeds', textKey: 'r1_a_exceeds', score: 2 },
                        { value: 'meets', textKey: 'r1_a_meets', score: 3 },
                        { value: 'partial', textKey: 'r1_a_partial', score: 5 },
                        { value: 'below', textKey: 'r1_a_below', score: 2 }
                    ],
                    decBOptions: [
                        { value: 'optA', textKey: 'r1_b_optA', score: 5 },
                        { value: 'optB', textKey: 'r1_b_optB', score: 2 },
                        { value: 'optC', textKey: 'r1_b_optC', score: 3 },
                        { value: 'optD', textKey: 'r1_b_optD', score: 1 }
                    ]
                },
                {
                    titleKey: 'round2_title',
                    briefingKey: 'round2_briefing',
                    decALabelKey: 'r2_decA_label',
                    decBLabelKey: 'r2_decB_label',
                    decAOptions: [
                        { value: 'approve', textKey: 'r2_a_approve', score: 2 },
                        { value: 'approve_cond', textKey: 'r2_a_approve_cond', score: 5 },
                        { value: 'reject_small', textKey: 'r2_a_reject_small', score: 4 },
                        { value: 'reject_buyback', textKey: 'r2_a_reject_buyback', score: 3 },
                        { value: 'table', textKey: 'r2_a_table', score: 3 }
                    ],
                    decBOptions: [
                        { value: 'review', textKey: 'r2_b_review', score: 5 },
                        { value: 'threshold', textKey: 'r2_b_threshold', score: 4 },
                        { value: 'reject', textKey: 'r2_b_reject', score: 2 },
                        { value: 'defer', textKey: 'r2_b_defer', score: 2 }
                    ]
                },
                {
                    titleKey: 'round3_title',
                    briefingKey: 'round3_briefing',
                    decALabelKey: 'r3_decA_label',
                    decBLabelKey: 'r3_decB_label',
                    decAOptions: [
                        { value: 'engage_full', textKey: 'r3_a_engage_full', score: 4 },
                        { value: 'conditional', textKey: 'r3_a_conditional', score: 3 },
                        { value: 'proxy_contest', textKey: 'r3_a_proxy_contest', score: 2 },
                        { value: 'partial', textKey: 'r3_a_partial', score: 5 }
                    ],
                    decBOptions: [
                        { value: 'defend', textKey: 'r3_b_defend', score: 1 },
                        { value: 'non_executive', textKey: 'r3_b_non_executive', score: 4 },
                        { value: 'lead_independent', textKey: 'r3_b_lead_independent', score: 4 },
                        { value: 'transition_12m', textKey: 'r3_b_transition_12m', score: 5 }
                    ]
                },
                {
                    titleKey: 'round4_title',
                    briefingKey: 'round4_briefing',
                    decALabelKey: 'r4_decA_label',
                    decBLabelKey: 'r4_decB_label',
                    decAOptions: [
                        { value: 'proactive', textKey: 'r4_a_proactive', score: 5 },
                        { value: 'measured', textKey: 'r4_a_measured', score: 3 },
                        { value: 'minimal', textKey: 'r4_a_minimal', score: 2 },
                        { value: 'defer_mgmt', textKey: 'r4_a_defer_mgmt', score: 1 }
                    ],
                    decBOptions: [
                        { value: 'internal', textKey: 'r4_b_internal', score: 4 },
                        { value: 'interim', textKey: 'r4_b_interim', score: 3 },
                        { value: 'external', textKey: 'r4_b_external', score: 2 },
                        { value: 'retain', textKey: 'r4_b_retain', score: 2 }
                    ]
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    gqiScore: 0,
                    decisionQualityTotal: 0,
                    processIntegrityTotal: 0,
                    riskOversightTotal: 0,
                    stakeholderCommTotal: 0,
                    stockPrice: 100,
                    whistleblowerChoice: '',
                    successionPlanned: false,
                    gqiHistory: [],
                    stockHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    decisionA: '',
                    decisionB: ''
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            this._renderRound((state && state.currentPeriod) || 1);
            var eventPanel = document.getElementById('eventPanel');
            if (eventPanel) eventPanel.style.display = 'none';
        }

        _renderRound(periodNum) {
            var idx = Math.min((periodNum || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = t(round.titleKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(round.briefingKey);

            var labelA = document.getElementById('decisionALabel');
            if (labelA) labelA.textContent = t(round.decALabelKey);

            var labelB = document.getElementById('decisionBLabel');
            if (labelB) labelB.textContent = t(round.decBLabelKey);

            var selA = document.getElementById('decisionAInput');
            if (selA) {
                selA.innerHTML = '';
                for (var i = 0; i < round.decAOptions.length; i++) {
                    var opt = document.createElement('option');
                    opt.value = round.decAOptions[i].value;
                    opt.textContent = t(round.decAOptions[i].textKey);
                    selA.appendChild(opt);
                }
            }

            var selB = document.getElementById('decisionBInput');
            if (selB) {
                selB.innerHTML = '';
                for (var j = 0; j < round.decBOptions.length; j++) {
                    var opt2 = document.createElement('option');
                    opt2.value = round.decBOptions[j].value;
                    opt2.textContent = t(round.decBOptions[j].textKey);
                    selB.appendChild(opt2);
                }
            }

        }

        validateDecisions(decisions) {
            var selA = document.getElementById('decisionAInput');
            if (selA) decisions.decisionA = selA.value;

            var selB = document.getElementById('decisionBInput');
            if (selB) decisions.decisionB = selB.value;

            if (!decisions.decisionA || !decisions.decisionB) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var scoreA = 1;
            for (var i = 0; i < round.decAOptions.length; i++) {
                if (round.decAOptions[i].value === d.decisionA) {
                    scoreA = round.decAOptions[i].score;
                    break;
                }
            }

            var scoreB = 1;
            for (var j = 0; j < round.decBOptions.length; j++) {
                if (round.decBOptions[j].value === d.decisionB) {
                    scoreB = round.decBOptions[j].score;
                    break;
                }
            }

            var roundGQI = Math.round((scoreA + scoreB) * 2.5);
            var decisionQuality = Math.round((scoreA + scoreB) * 1.5);
            var processIntegrity = Math.round(((scoreA >= 4 ? 3 : 1) + (scoreB >= 4 ? 3 : 1)) * 1.0);
            var riskOversight = Math.round(scoreB * 2.0);
            var stakeholderComm = Math.round(scoreA * 1.5);

            var stockDelta = 0;
            var avgScore = (scoreA + scoreB) / 2;
            if (avgScore >= 4.5) stockDelta = 4;
            else if (avgScore >= 3.5) stockDelta = 2;
            else if (avgScore >= 2.5) stockDelta = 0;
            else if (avgScore >= 1.5) stockDelta = -3;
            else stockDelta = -6;

            if (state.currentPeriod === 1 && d.decisionB) {
                state.domainState.whistleblowerChoice = d.decisionB;
            }

            if (state.currentPeriod === 4) {
                var wbChoice = state.domainState.whistleblowerChoice;
                if (wbChoice === 'optA') {
                    stockDelta += 5;
                    roundGQI += 3;
                } else if (wbChoice === 'optB' || wbChoice === 'optC') {
                    stockDelta -= 4;
                    roundGQI -= 2;
                } else if (wbChoice === 'optD') {
                    stockDelta -= 10;
                    roundGQI -= 5;
                }
            }

            roundGQI = Math.max(0, Math.min(25, roundGQI));

            state.domainState.gqiScore += roundGQI;
            state.domainState.decisionQualityTotal += decisionQuality;
            state.domainState.processIntegrityTotal += processIntegrity;
            state.domainState.riskOversightTotal += riskOversight;
            state.domainState.stakeholderCommTotal += stakeholderComm;
            state.domainState.stockPrice = Math.round(state.domainState.stockPrice * (1 + stockDelta / 100));

            state.domainState.gqiHistory.push(roundGQI);
            state.domainState.stockHistory.push(state.domainState.stockPrice);

            var eventText = this._getOutcomeText(state.currentPeriod, d, scoreA, scoreB, state);
            var eventPanel = document.getElementById('eventPanel');
            var eventTextEl = document.getElementById('eventText');
            if (eventPanel && eventTextEl) {
                eventPanel.style.display = 'block';
                eventTextEl.innerHTML = eventText;
            }

            // Advance the briefing + decision controls to the NEXT round immediately,
            // before the framework increments currentPeriod, using the correct next value.
            // (The previous setTimeout read state.currentPeriod AFTER the engine had already
            //  incremented it, jumping the briefing one round ahead and desyncing scoring.)
            // The Outcome Report is intentionally left visible so the player can read the
            // feedback for the meeting they just completed; it is replaced on the next submit.
            var nextPeriod = (state.currentPeriod || 1) + 1;
            var maxP = state.maxPeriods || this.ROUNDS.length;
            if (nextPeriod <= maxP) {
                this._renderRound(nextPeriod);
            }

            return {
                period: state.currentPeriod,
                decisionA: d.decisionA,
                decisionB: d.decisionB,
                scoreA: scoreA,
                scoreB: scoreB,
                roundGQI: roundGQI,
                cumulativeGQI: state.domainState.gqiScore,
                stockPrice: state.domainState.stockPrice,
                stockDelta: stockDelta
            };
        }

        _getOutcomeText(period, decisions, scoreA, scoreB, state) {
            var t = window.mySimulation.t.bind(window.mySimulation);
            var avg = (scoreA + scoreB) / 2;
            var key = 'outcome_r' + period + '_';
            if (avg >= 4) key += 'good';
            else if (avg >= 3) key += 'moderate';
            else key += 'poor';
            return t(key);
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('gqiDisplay', 'domainState.gqiScore',
                function(v) { return Math.round(v) + ' / 100'; });
            uiManager.bind('stockDisplay', 'domainState.stockPrice',
                function(v) { return Math.round(v); });
            uiManager.bind('decisionQualityDisplay', 'domainState.decisionQualityTotal',
                function(v) { return Math.round(v); });
            uiManager.bind('riskDisplay', 'domainState.riskOversightTotal',
                function(v) { return Math.round(v); });
        }

        getChartConfig() {
            return {
                gqiChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'GQI per Meeting',
                            data: [],
                            backgroundColor: [
                                'rgba(43,108,176,0.7)',
                                'rgba(56,161,105,0.7)',
                                'rgba(214,158,46,0.7)',
                                'rgba(229,62,62,0.7)'
                            ],
                            borderColor: [
                                '#2b6cb0',
                                '#38a169',
                                '#d69e2e',
                                '#e53e3e'
                            ],
                            borderWidth: 2,
                            borderRadius: 8
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Governance Quality per Board Meeting' },
                            legend: { display: false }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 25, title: { display: true, text: 'GQI Points' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.gqiHistory.map(function(_, i) { return 'Meeting ' + (i + 1); });
            return {
                gqiChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.gqiHistory }]
                }
            };
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.decisionA', label: 'Primary Decision', i18nKey: 'col_dec_a' },
                { key: 'results.decisionB', label: 'Secondary Decision', i18nKey: 'col_dec_b' },
                { key: 'results.roundGQI', label: 'GQI Points', i18nKey: 'col_gqi', formatter: function(v) { return v + ' / 25'; } },
                { key: 'results.cumulativeGQI', label: 'Cumulative GQI', i18nKey: 'col_cum_gqi', formatter: function(v) { return v + ' / 100'; } },
                { key: 'results.stockPrice', label: 'Stock Index', i18nKey: 'col_stock' },
                { key: 'results.stockDelta', label: 'Stock Change', i18nKey: 'col_stock_delta', formatter: function(v) { return (v >= 0 ? '+' : '') + v + '%'; } }
            ];
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var gqiScores = history.map(function(r) { return r.results ? r.results.roundGQI || 0 : 0; });
            var totalGQI = gqiScores.reduce(function(s, v) { return s + v; }, 0);
            var avgGQI = totalGQI / gqiScores.length;
            var finalStock = history.length > 0 && history[history.length - 1].results ? history[history.length - 1].results.stockPrice : 100;

            var performance = 'Needs Improvement';
            if (totalGQI >= 80 && finalStock >= 108) performance = 'Exemplary Board';
            else if (totalGQI >= 65 && finalStock >= 100) performance = 'Effective Board';
            else if (totalGQI >= 50) performance = 'Adequate Board';

            var insights = [];
            if (totalGQI >= 80) {
                insights.push('Outstanding governance discipline across all four board meetings.');
            } else if (totalGQI >= 65) {
                insights.push('Solid governance with room for improvement in some areas.');
            } else if (totalGQI >= 50) {
                insights.push('Governance decisions were adequate but process integrity needs strengthening.');
            } else {
                insights.push('The board deferred too frequently to management, weakening oversight.');
            }

            if (finalStock < 90) {
                insights.push('Governance failures eroded shareholder value significantly.');
            }

            return {
                totalGQI: totalGQI,
                avgGQI: Math.round(avgGQI * 10) / 10,
                finalStockIndex: finalStock,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var avg = ((results.scoreA || 0) + (results.scoreB || 0)) / 2;
            if (avg <= 2) return window.mySimulation.t('hint_poor');
            if (avg <= 3) return window.mySimulation.t('hint_moderate');
            if (avg >= 4.5) return window.mySimulation.t('hint_excellent');
            return null;
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:                `Board Effectiveness: Corporate Governance`,
                    subtitle:             `Meridia Corporation — Board Simulation`,
                    period_label:         `Board Meeting`,
                    period_of:            `of`,
                    gqi_label:            `Governance Quality Index`,
                    stock_label:          `Stock Price Index`,
                    decision_quality_label: `Decision Quality`,
                    risk_label:           `Risk Oversight`,
                    decisions_heading:    `Board Decisions`,
                    submit_btn:           `Submit Decisions`,
                    undo_btn:             `Undo Last Meeting`,
                    select_warning:       `Please select an option for both decisions.`,
                    event_heading:        `Outcome Report`,

                    round1_title:         `Board Meeting 1: CEO Performance Review`,
                    round1_briefing:      `Meridia Corporation (Revenue $4.2B, EBITDA 15%) has completed a strong fiscal year under CEO Diego Castellanos. Financial targets were met or exceeded, but employee engagement (67 vs 75 target), ESG score, and succession planning are significantly behind. The Audit Committee Chair has received a whistleblower complaint alleging revenue manipulation in the Commercial Real Estate division. The CEO urges the board to treat the complaint with discretion.<br><br>You must evaluate the CEO and decide how to handle the whistleblower complaint.`,

                    r1_decA_label:        `CEO Performance Rating`,
                    r1_a_exceeds:         `Exceeds Expectations — Full bonus and LTIP vesting`,
                    r1_a_meets:           `Meets Expectations — Standard LTIP vesting`,
                    r1_a_partial:         `Partially Meets — Reduced LTIP; accountability message on governance gaps`,
                    r1_a_below:           `Does Not Meet — No LTIP; formal improvement plan`,
                    r1_decB_label:        `Whistleblower Complaint Response`,
                    r1_b_optA:            `Option A: Immediate independent investigation by external counsel`,
                    r1_b_optB:            `Option B: Internal management review first; defer external investigation`,
                    r1_b_optC:            `Option C: External auditor assessment; report in 30 days`,
                    r1_b_optD:            `Option D: Routine audit matter; defer entirely to management`,

                    round2_title:         `Board Meeting 2: Capital Allocation Decision`,
                    round2_briefing:      `CEO Castellanos proposes acquiring Construtora Horizonte in Brazil for $1.8B, which would push leverage to 4.2x Net Debt/EBITDA and likely trigger a credit downgrade from BBB to BB. Management claims $180M in annual synergies by Year 3. Independent analysis shows Meridia trades at a 15% conglomerate discount (13.2x P/E vs 16-18x for pure-play peers). Cascade Capital (9% shareholder) argues the conglomerate structure destroys value.<br><br>You must decide on the acquisition and address the conglomerate discount concern.`,

                    r2_decA_label:        `Brazil Acquisition Vote`,
                    r2_a_approve:         `Approve acquisition as proposed by management`,
                    r2_a_approve_cond:    `Approve with conditions: independent fairness opinion, synergy audit, staged financing`,
                    r2_a_reject_small:    `Reject; pursue smaller LATAM acquisitions in existing markets ($600M)`,
                    r2_a_reject_buyback:  `Reject; return $800M to shareholders via buyback and dividends`,
                    r2_a_table:           `Table for further independent analysis`,
                    r2_decB_label:        `Conglomerate Discount Response`,
                    r2_b_review:          `Commission independent strategic review of conglomerate structure`,
                    r2_b_threshold:       `Set 18-month performance threshold; review if P/E remains below 15x`,
                    r2_b_reject:          `Formally reject the restructuring thesis; reaffirm conglomerate strategy`,
                    r2_b_defer:           `Defer question until after the acquisition decision`,

                    round3_title:         `Board Meeting 3: Activist Investor Response`,
                    round3_briefing:      `Cascade Capital Partners (9% stake) has publicly demanded: two board seats, strategic review, replacement of the Executive Chair with an Independent Chair, and $500M capital return. ISS recommends shareholders vote FOR two Cascade nominees and WITHHOLD votes from the Chair due to undisclosed related-party transactions. Institutional shareholders holding 30% are watching closely.<br><br>You must decide on the engagement strategy and address the Chair position.`,

                    r3_decA_label:        `Activist Engagement Strategy`,
                    r3_a_engage_full:     `Engage fully: meet Cascade, acknowledge governance concerns, explore common ground`,
                    r3_a_conditional:     `Conditional engagement: meet only with standstill agreement in place`,
                    r3_a_proxy_contest:   `Proxy contest: refuse board seats; fight at AGM`,
                    r3_a_partial:         `Partial accommodation: accept 1 nominee; commit to strategic review; reject forced capital return`,
                    r3_decB_label:        `Board Chair Position`,
